import gzip,hashlib,json,re
from pathlib import Path
import numpy as np
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
from matplotlib.lines import Line2D
out=Path('/tmp/prosac-report');out.mkdir(exist_ok=True)
columns=['pair','seed','median_us','iqr_us','sampled_sets','max_err','failed','timing_block_calls']
def frontier(rows):
 return sorted([r for r in rows if not any(o['time_ms']<=r['time_ms'] and o['maa']>=r['maa'] and (o['time_ms']<r['time_ms'] or o['maa']>r['maa']) for o in rows)],key=lambda r:r['time_ms'])
def baseline(r):return r['max_lo_iters']==5 and r['lo_sample_size'] is None and r['threads']==1 and r['method']=='standard'
records=[];sources={};counts_by_feature={}
for stage,directory in [('screening','/tmp/prosac-wallclock'),('validation','/tmp/prosac-validation')]:
 for p in sorted(Path(directory).glob('*-eval.json')):
  d=json.loads(p.read_text());meta=d['metadata'];name=p.stem.removesuffix('-eval');sources[stage+'/'+name]={k:v for k,v in meta.items() if k!='quality_summary'}
  sources[stage+'/'+name]['raw_evaluated_sha256']=hashlib.sha256(p.read_bytes()).hexdigest()
  for item in d['results']:counts_by_feature.setdefault(item['feature'],{})[item['pair']]=item['correspondences']
  for s in meta['quality_summary']:
   rows=[r for r in d['results'] if all(r.get(k)==s.get(k) for k in ('feature','batch','prosac','max_lo_iters','lo_sample_size'))]
   times=[r['median_us']/1000 for r in rows if r['median_us'] is not None]
   r=dict(stage=stage,run=name,device=meta['device'],feature=s['feature'],batch=s['batch'],budget=meta['sample_budget'],prosac=s['prosac'],max_lo_iters=s['max_lo_iters'],lo_sample_size=s.get('lo_sample_size'),threads=meta['torch_num_threads'],method=s.get('method','standard'),maa=s['maa'],failure_rate=s['failure_rate'],time_ms=float(np.mean(times)),mean_sampled_sets=float(np.mean([r['sampled_sets'] for r in rows])),timed_rows=len(times),total_rows=len(rows),errors=sum('error' in r for r in rows),cells=s['cells'],pair_results=[[r.get(c) for c in columns] for r in rows])
   r['baseline_policy']=baseline(r);records.append(r)
for r in records:
 group=[x for x in records if (x['stage'],x['device'],x['feature'])==(r['stage'],r['device'],r['feature'])]
 r['frontier']=r in frontier(group)
 r['baseline_frontier']=r['baseline_policy'] and r in frontier([x for x in group if x['baseline_policy']])
scripts={}
for name in ['prosac-wallclock-run.py','prosac-wallclock-expand.py','prosac-grid-benchmark.py','prosac-grid-check.py','prosac-validation-benchmark.py','prosac-wallclock-validate.py','prosac-wallclock-controls.py','prosac-spatial.py','prosac-confidence.py','prosac-numerical.py','prosac-report.py']:
 p=Path('/tmp')/name
 scripts[name]={'sha256':hashlib.sha256(p.read_bytes()).hexdigest(),'source':p.read_text()}
selection=Path('/tmp/prosac-validation/selection-with-controls.json')
primary_selection=json.loads(Path('/tmp/prosac-validation/selection.json').read_text())
report={'metadata':{'objective':'empirical wall-clock / pose-mAA Pareto frontiers, separately per matcher and device','base_commit':'dfac11ab','threshold_px':1,'confidence':.999,'score':'msac','model':'fundamental eight-point','screening_scenes':['sacre_coeur','reichstag','st_peters_square'],'validation_scenes':['british_museum','florence_cathedral_side','lincoln_memorial_statue','london_bridge'],'validation_caveat':'40 configurations selected on screening before validation; six same-budget grid controls added after primary validation. The four validation scenes previously appeared in the stopping study, so this is not untouched holdout. Frontier is among evaluated configurations only.','correspondence_counts':{feature:{'pairs':len(values),'min':min(values.values()),'max':max(values.values()),'median':float(np.median(list(values.values()))),'mean':float(np.mean(list(values.values())))} for feature,values in counts_by_feature.items()},'pair_result_columns':columns,'primary_validation_selection':primary_selection,'validation_selection':json.loads(selection.read_text()) if selection.exists() else None,'runs':sources,'experiment_sources':scripts},'results':records}
details={'pair_result_columns':columns,'results':[],'diagnostics':{name:json.loads((Path('/tmp/prosac-wallclock')/(name+'.json')).read_text()) for name in ['spatial','confidence','numerical']}}
for r in records:
 r['matched_control_added_after_primary_selection']=r['stage']=='validation' and r['run'] not in primary_selection
 r['id']=f"{r['stage']}/{r['run']}/{r['feature']}/p{int(r['prosac'])}"
 details['results'].append({'id':r['id'],'rows':r.pop('pair_results')})
detail_bytes=gzip.compress(json.dumps(details,sort_keys=True,allow_nan=False).encode(),mtime=0)
(out/'prosac_pareto_pairs.json.gz').write_bytes(detail_bytes)
report['metadata']['pair_results_file']='prosac_pareto_pairs.json.gz'
report['metadata']['pair_results_sha256']=hashlib.sha256(detail_bytes).hexdigest()
(out/'prosac_pareto.json').write_text(json.dumps(report,indent=2,sort_keys=True,allow_nan=False)+'\n')
for stage in ['screening','validation']:
 fig,axes=plt.subplots(2,2,figsize=(12,8),sharey='row')
 for i,feature in enumerate(['aliked_lightglue','roma']):
  for j,device in enumerate(['cpu','cuda']):
   ax=axes[i,j];rs=[r for r in records if (r['stage'],r['feature'],r['device'])==(stage,feature,device)]
   if not rs:continue
   for label,color,select in [('Full-inlier LO≤5, 1 thread','#3978b4',lambda r:baseline(r)),('LO / thread variants','#e18a28',lambda r:not baseline(r) and r['method']=='standard'),('Joint-cell PROSAC','#2b9b66',lambda r:r['method']=='coverage-prosac')]:
    group=[r for r in rs if select(r)]
    for sampler in [False,True]:
     points=[r for r in group if r['prosac']==sampler]
     if not points:continue
     marker='s' if points[0]['method']=='coverage-prosac' else ('^' if sampler else 'o')
     ax.scatter([r['time_ms'] for r in points],[r['maa'] for r in points],color=color,alpha=.65,s=25,marker=marker,label=label)
     label='_nolegend_'
   for label,color,group,style in [('Baseline envelope','#3978b4',[r for r in rs if baseline(r)],'-'),('Combined envelope','#c15d12',rs,'--')]:
    f=frontier(group);ax.plot([r['time_ms'] for r in f],[r['maa'] for r in f],style,color=color,linewidth=1.5,label=label)
   ax.set_xscale('log');ax.set_xlabel('Mean per-pair RANSAC time (ms; log scale)');ax.set_ylabel('Pose mAA (1–10°)');ax.grid(alpha=.2)
   ax.set_title(('ALIKED + LightGlue' if feature=='aliked_lightglue' else 'RoMa')+' · '+device.upper())
 handles,labels=axes[0,0].get_legend_handles_labels()
 for label,marker in [('Uniform','o'),('PROSAC','^')]:
  handles.append(Line2D([0],[0],marker=marker,linestyle='None',color='gray'));labels.append(label)
 # RoMa-only grid points may be absent from the first panel.
 if 'Joint-cell PROSAC' not in labels:
  handles.append(Line2D([0],[0],marker='s',linestyle='None',color='#2b9b66'));labels.append('Joint-cell PROSAC')
 fig.legend(handles,labels,loc='lower center',ncol=3,fontsize=9)
 fig.suptitle(('Screening: 30 pairs / matcher; timing subset' if stage=='screening' else 'Validation: 40 pairs / matcher; every pair timed')+' · 3 seeds · fixed 1 px MSAC',fontsize=13)
 fig.tight_layout(rect=(0,.12,1,.96));fig.savefig(out/f'prosac_pareto_{stage}.png',dpi=180);plt.close(fig)
for stage in ['screening','validation']:
 print(stage.upper())
 for r in records:
  if r['stage']==stage and r['frontier']:print(r['device'],r['feature'],r['run'],r['prosac'],round(r['maa'],4),round(r['time_ms'],2))
print('CONFIGS',len(records),'ROWS',sum(r['total_rows'] for r in records),'ERRORS',sum(r['errors'] for r in records))
lines=['## Validation frontiers','', '![Validation time–mAA curves](prosac_pareto_validation.png)','', 'The table includes the combined empirical frontier and any superseded baseline-frontier points.', 'These are observed envelopes, not statistically established dominance. Asterisks identify post-hoc', 'controls appearing in the table; six same-budget ordering controls were evaluated overall.','']
for device in ['cpu','cuda']:
 for feature in ['aliked_lightglue','roma']:
  lines+=['### '+device.upper()+' / '+('ALIKED + LightGlue' if feature=='aliked_lightglue' else 'RoMa'),'', '| Sampler | Batch / max draws | LO max / subset cap | Threads | ms | mAA | Envelope |','|---|---:|---:|---:|---:|---:|---|']
  group=[r for r in records if (r['stage'],r['device'],r['feature'])==('validation',device,feature) and (r['frontier'] or r['baseline_frontier'])]
  for r in sorted(group,key=lambda r:r['time_ms']):
   sampler='Grid PROSAC' if r['method']=='coverage-prosac' else ('PROSAC' if r['prosac'] else 'Uniform')
   if r['matched_control_added_after_primary_selection']:sampler+='*'
   cap=r['lo_sample_size'] if r['lo_sample_size'] is not None else 'full'
   lines.append(f"| {sampler} | {r['batch']} / {r['budget']} | {r['max_lo_iters']} / {cap} | {r['threads']} | {r['time_ms']:.2f} | {r['maa']:.4f} | {'Combined' if r['frontier'] else 'Baseline only'} |")
  lines.append('')
lines+=['## Screening curves','','![Screening time–mAA curves](prosac_pareto_screening.png)','','Screening and validation contain different scenes and timing regimes; compare policies within', 'each plot. Do not join points across the two sets. All screening configurations, including', 'dominated ones, remain in the JSON.','']
(out/'tables.md').write_text('\n'.join(lines))

