import json
from pathlib import Path
import numpy as np
rows=[]
with np.load('/tmp/prosac-learned-140.npz') as d:
 for key in sorted(k[:-7] for k in d.files if k.endswith('__mkp_a')):
  a,b=d[key+'__mkp_a'],d[key+'__mkp_b'];order=np.argsort(d[key+'__score'].reshape(-1),kind='stable')
  p=np.concatenate((a[order],b[order]),axis=1);lo=p.min(0);width=np.maximum(np.ptp(p,axis=0),1e-8);q=(p-lo)/width
  cells=np.minimum((q*4).astype(int),3);keys=((cells[:,0]*4+cells[:,1])*4+cells[:,2])*4+cells[:,3]
  counts={};depth=[]
  for c in keys:depth.append(counts.get(int(c),0));counts[int(c)]=counts.get(int(c),0)+1
  grid=np.lexsort((np.arange(len(p)),depth))
  for name,indices in [('confidence',np.arange(len(p))),('grid',grid)]:
   for n in [8,32,128,len(p)]:
    for side in [0,1]:
     v=q[indices[:n],side*2:side*2+2];cell=cells[indices[:n],side*2:side*2+2]
     rows.append(dict(pair=key,feature=key.split('__')[1],ordering=name,prefix=n,side=side,cells=len(np.unique(cell,axis=0)),bbox_area=float(np.prod(np.ptp(v,axis=0)))))
Path('/tmp/prosac-wallclock/spatial.json').write_text(json.dumps(rows))
for feature in ['aliked_lightglue','roma']:
 for name in ['confidence','grid']:
  for n in [8,32,128]:
   r=[x for x in rows if x['feature']==feature and x['ordering']==name and x['prefix']==n]
   print(feature,name,n,'median cells',np.median([x['cells'] for x in r]),'median bbox',round(np.median([x['bbox_area'] for x in r]),3))
